\documentclass{article}
\usepackage{tikz}
\usepackage{pgfplots}
\usetikzlibrary{arrows.meta, calc, decorations.markings, decorations.pathreplacing}
\usepackage{amsmath}
\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty}

\begin{tikzpicture}[
declare function={
% vector field
	f(\x,\y) = (1)*\x + (-1)*\y;
	g(\x,\y) = (1)*\x + (-1)*\y; 
}]

\begin{axis}[
    tick label style={font=\footnotesize},
    label style={font=\small},
    tick style={thick, black},
    view={0}{90},
    minor tick style={draw=none},
    axis line style = thick,
    axis y line = center,
    axis x line = middle,
    axis equal,  
    xmin = -5,
    xmax = 5,
    ymin = -5,
    ymax = 5,
    xtick = {0}, ytick = {0},
    minor xtick={-28,-24,...,28},
    minor ytick={-28,-24,...,28},    
    xlabel = {$x$}, ylabel = {$y$},
    xlabel style={below right}, ylabel style={above left},
    every axis x label/.style={at={(ticklabel* cs:1.02)}, anchor=west,},
    every axis y label/.style={at={(ticklabel* cs:1.02)}, anchor=south,}
]

% Vector field of tangents 
% (note that arrows are normalized to have the same magnitude)
\plot3 [
	quiver= {
			u={ f(x,y) / sqrt((f(x,y))^2 + (g(x,y))^2) },
			v={ g(x,y) / sqrt((f(x,y))^2 + (g(x,y))^2) },
    		scale arrows=0.4
    	},
		-stealth, color=gray, samples=16, opacity=0.6,
		domain = -5:5,
		domain y = -4.5:4.5,
	] {0};

% Equilibriums
\draw[fadedpink, dotted, ultra thick] plot[domain=-5:5, variable=\t, samples=200] 
	(axis cs: {1*\t}, {1*\t});


% Straight-line solutions

\draw[deepskyblue, thick, decoration={markings, mark = between positions 0.1 and 0.9 step 0.2 with {\arrow{>}}}, postaction={decorate}] plot[domain=-4:4, variable=\t, samples=200] 
	(axis cs: {1*\t+(2)*1}, {1*\t-(2)*1});

\draw[deepskyblue, thick, decoration={markings, mark = between positions 0.1 and 0.9 step 0.2 with {\arrow{>}}}, postaction={decorate}] plot[domain=-4:4, variable=\t, samples=200] 
	(axis cs: {1*\t+(1)*1}, {1*\t-(1)*1});

\draw[deepskyblue, thick, decoration={markings, mark = between positions 0.1 and 0.9 step 0.2 with {\arrow{>}}}, postaction={decorate}] plot[domain=4:-4, variable=\t, samples=200] 
	(axis cs: {1*\t+(-2)*1}, {1*\t-(-2)*1});

\draw[deepskyblue, thick, decoration={markings, mark = between positions 0.1 and 0.9 step 0.2 with {\arrow{>}}}, postaction={decorate}] plot[domain=4:-4, variable=\t, samples=200] 
	(axis cs: {1*\t+(-1)*1}, {1*\t-(-1)*1});

\end{axis}
\end{tikzpicture}
\end{document}
